<template>
  <view
    v-if="visible"
    :class="['popup', type]"
    class="alert-popup"
  >
    {{ message }}
  </view>
</template>

<script setup>
import { ref } from 'vue'

const visible = ref(false)
const message = ref('')
const type = ref('success') // 'success' or 'error'

/**
 * 外部调用此函数触发弹窗
 * @param {string} msg 提示文字
 * @param {string} msgType 'success' | 'error'
 */
function showAlert(msg, msgType = 'success') {
  message.value = msg
  type.value = msgType
  visible.value = true
  setTimeout(() => {
    visible.value = false
  }, 2000) // 自动消失时间
}

defineExpose({ showAlert }) // 让父组件可调用
</script>

<style scoped>
.alert-popup {
  position: fixed;
  top: 10px;
  left: 50%;
  transform: translateX(-50%);
  padding: 12px 24px;
  border-radius: 10px;
  font-size: 14px;
  color: white;
  z-index: 999;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
}
.success {
  background-color: #4caf50;
}
.error {
  background-color: #f44336;
}
</style>